import { OrderRepository } from '../../domain/order/OrderRepository';
import { StockReservationService } from '../../domain/services/StockReservationService';
import { OrderDto, toOrderDto } from '../dto/OrderDto';
import { requireOrder } from '../services/requireOrder';

/** Cancels an order that has not yet shipped and returns its reserved stock. */
export class CancelOrderUseCase {
  constructor(
    private readonly orders: OrderRepository,
    private readonly stock: StockReservationService,
  ) {}

  execute(orderId: string): OrderDto {
    const order = requireOrder(this.orders, orderId);

    order.cancel();
    this.stock.release(order.lines);
    this.orders.save(order);
    return toOrderDto(order);
  }
}

=====SOURCE-END=====

