import { Order } from '../../domain/order/Order';
import { OrderLine } from '../../domain/order/OrderLine';
import { OrderRepository } from '../../domain/order/OrderRepository';
import { StockReservationService } from '../../domain/services/StockReservationService';
import { OrderDto, PlaceOrderCommand, toOrderDto } from '../dto/OrderDto';

export class PlaceOrderUseCase {
  constructor(
    private readonly orders: OrderRepository,
    private readonly stock: StockReservationService,
  ) {}

  execute(command: PlaceOrderCommand): OrderDto {
    const lines = command.lines.map((line) => OrderLine.of(line.productId, line.quantity));
    const order = Order.place(this.orders.nextId(), command.customerId, lines, new Date());

    this.stock.reserve(order.lines);
    this.orders.save(order);
    return toOrderDto(order);
  }
}

